 spot=P('Born from two real clues: the Dibdibba gravels of northern Kuwait came from the Arabian Shield far to the west, and Farouk El-Baz traced the dry channel of an ancient river, which he called the Kuwait River, across Arabia on satellite images.',
        'وُلدت الفكرة من دليلين حقيقيين: حصى الدبدبة في شمال الكويت جاء من الدرع العربي في الغرب البعيد، وتتبّع فاروق الباز في الصور الفضائية القناة الجافة لنهر قديم عبر الجزيرة العربية سمّاه نهر الكويت.'),
 lk=[['wadi-al-batin', 'The dry valley El-Baz traced', 'الوادي الجاف الذي تتبّعه الباز'],
     ['dibdibba-alluvial-fan', 'Gravel the river carried from western Arabia', 'حصى حمله النهر من غرب الجزيرة العربية'],
     ['wadi-batin-playas', 'Playas that fill along the wadi', 'فيضات تمتلئ على امتداد الوادي'],
     ['jahra-freshwater-lens', 'Fresh water under Jahra', 'مياه عذبة تحت الجهراء'],
     ['atraf-ancient-wells', 'Old wells near the edge of the fan', 'آبار قديمة قرب حافة المروحة'],
     ['kadhima', 'The caravan stop with sweet water', 'محطة القوافل ذات الماء العذب']],
